    other = -0.75
    out = np.empty_like(input)
    list_of_inputs.append(copy.deepcopy({"input": input, "other": other, "out": out}))

    # 11
    input = np.array([np.nan, np.inf, -np.inf, 1.0], dtype=np.float64)
