    input_dict = {"input": inp_t.numpy(), "out": out_t.numpy()}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 11: int64 5D -> out float64
    inp_t = (torch.arange(12, dtype=torch.int64) - 6).reshape(1, 2, 1, 2, 3)
