def fftshift_2_inputs():
    list_of_inputs = []
    
    # Input 1: 1D even length, float64
    arr = torch.arange(8, dtype=torch.float64).numpy()
    dim = (0,)
    list_of_inputs.append(copy.deepcopy({"input": arr, "dim": dim}))
    
    # Input 2: 1D odd length, complex64
