import numpy as np

def logsumexp_inputs():
    def compute_out(arr, dims, keepdim):
        nd = arr.ndim
        dims_pos = tuple(d if d >= 0 else nd + d for d in dims)
        shape = []
        for i in range(nd):
            if i in dims_pos:
                if keepdim:
                    shape.append(1)
            else:
                shape.append(arr.shape[i])
        return np.empty(tuple(shape), dtype=arr.dtype)

    list_of_inputs = []

