    LU_data = torch.arange(2*3*3, dtype=torch.float64).reshape(2, 3, 3).sub(5.0).numpy()
    LU_pivots = torch.tensor([[1, 3, 2],
                              [3, 2, 2]], dtype=torch.int32).numpy()
