import torch, copy
import numpy as np

class IndexableInt(int):
    def __new__(cls, value):
        return int.__new__(cls, int(value))
    def __len__(self):
        return 1
    def __iter__(self):
        yield int(self)
    def __getitem__(self, idx):
        if idx in (0, -1):
            return int(self)
        raise IndexError("Index out of range for IndexableInt")

def torch_max_3_inputs():
    list_of_inputs = []

    def make_case(arr, dim_scalar, keepdim):
        ndim = arr.ndim
        d = int(dim_scalar)
        d_eff = d if d >= 0 else d + ndim
        assert 0 <= d_eff < ndim
        out_shape = list(arr.shape)
        if keepdim:
            out_shape[d_eff] = 1
        else:
            out_shape.pop(d_eff)
        values_out = np.empty(out_shape, dtype=arr.dtype)
        indices_out = np.empty(out_shape, dtype=np.int64)
        return {
            "input": arr,
            "dim": IndexableInt(d),
            "keepdim": keepdim,
            "out": (values_out, indices_out)
        }

    a1 = np.array([[0.5, -1.2, 3.4, 2.2],
                   [4.1, -0.7, 0.0, 5.0],
                   [-3.0, -2.0, -1.0, -4.0]], dtype=np.float32)
    list_of_inputs.append(copy.deepcopy(make_case(a1, 1, False)))

    a2 = (np.arange(12, dtype=np.float32).reshape(3, 4) - 6.0).astype(np.float32)
    list_of_inputs.append(copy.deepcopy(make_case(a2, -1, True)))

    a3 = np.array([10, -5, 7, 7, -1], dtype=np.int64)
    list_of_inputs.append(copy.deepcopy(make_case(a3, 0, True)))

    a4 = np.random.randn(2, 3, 4).astype(np.float64)
    list_of_inputs.append(copy.deepcopy(make_case(a4, 2, True)))

    a5 = np.random.uniform(-1, 1, (2, 2, 3, 4)).astype(np.float16)
    list_of_inputs.append(copy.deepcopy(make_case(a5, 0, False)))

    a6 = (np.arange(4*1*5, dtype=np.int32).reshape(4, 1, 5) - 10).astype(np.int32)
    list_of_inputs.append(copy.deepcopy(make_case(a6, 1, False)))

    a7 = np.array([[True, False, True, True, False],
                   [False, False, True, False, True]], dtype=np.bool_)
    list_of_inputs.append(copy.deepcopy(make_case(a7, 0, True)))

    a8 = (np.random.randn(2, 4, 3) * 5 - 2).astype(np.float32)
    list_of_inputs.append(copy.deepcopy(make_case(a8, -2, False)))

    a9 = np.array([[[42.0, -3.0, 7.0],
                    [0.0, 0.0, 0.0]]], dtype=np.float32)
    list_of_inputs.append(copy.deepcopy(make_case(a9, 2, False)))

    a10 = (np.arange(2*3*4*2*3, dtype=np.int16).reshape(2, 3, 4, 2, 3) - 50).astype(np.int16)
    list_of_inputs.append(copy.deepcopy(make_case(a10, 3, False)))

    a11 = (np.random.randint(-128, 127, size=(8, 2))).astype(np.int8)
    list_of_inputs.append(copy.deepcopy(make_case(a11, 0, False)))

    a12 = np.linspace(-5, 5, 30, dtype=np.float64).reshape(3, 5, 2)
    list_of_inputs.append(copy.deepcopy(make_case(a12, -3, True)))

    return list_of_inputs

generated_inputs["torch.max_3"] = torch_max_3_inputs()

import torch, copy
import numpy as np

def maximum_inputs():
    list_of_inputs = []

    # Input 1: 1D int64
    input_arr = np.array([1, 2, -1], dtype=np.int64)
    other_arr = np.array([3, 0, 4], dtype=np.int64)
    out_arr = np.empty(np.broadcast(input_arr, other_arr).shape, dtype=input_arr.dtype)
    list_of_inputs.append(copy.deepcopy({"input": input_arr, "other": other_arr, "out": out_arr}))

    # Input 2: 1D float32 with NaNs
    input_arr = np.array([np.nan, -2.5, 0.0, 3.1], dtype=np.float32)
    other_arr = np.array([0.5, np.nan, -1.0, 2.9], dtype=np.float32)
    out_arr = np.empty(np.broadcast(input_arr, other_arr).shape, dtype=input_arr.dtype)
    list_of_inputs.append(copy.deepcopy({"input": input_arr, "other": other_arr, "out": out_arr}))

    # Input 3: 2D int32
    input_arr = np.array([[1, -2, 3], [4, -5, 6]], dtype=np.int32)
    other_arr = np.array([[0, 5, -3], [7, 1, 2]], dtype=np.int32)
    out_arr = np.empty(np.broadcast(input_arr, other_arr).shape, dtype=input_arr.dtype)
    list_of_inputs.append(copy.deepcopy({"input": input_arr, "other": other_arr, "out": out_arr}))

    # Input 4: Broadcast 2D float64 (3,1) vs (1,4)
    input_arr = np.array([[1.5], [-2.0], [0.0]], dtype=np.float64)
    other_arr = np.array([[0.0, -3.0, 2.2, 5.5]], dtype=np.float64)
    out_arr = np.empty(np.broadcast(input_arr, other_arr).shape, dtype=input_arr.dtype)
    list_of_inputs.append(copy.deepcopy({"input": input_arr, "other": other_arr, "out": out_arr}))

    # Input 5: Scalar int16 vs vector
    input_arr = np.array(-7, dtype=np.int16)
    other_arr = np.array([1, -8, 9], dtype=np.int16)
    out_arr = np.empty(np.broadcast(input_arr, other_arr).shape, dtype=input_arr.dtype)
    list_of_inputs.append(copy.deepcopy({"input": input_arr, "other": other_arr, "out": out_arr}))

    # Input 6: 3D float16 with broadcast (2,1,3) vs (1,4,1) -> (2,4,3)
    input_arr = np.array([[[1.0, -1.0, 0.5]], [[-0.5, 2.0, -3.0]]], dtype=np.float16)
    other_arr = np.array([[[0.0], [1.5], [-2.0], [3.0]]], dtype=np.float16)
    out_arr = np.empty(np.broadcast(input_arr, other_arr).shape, dtype=input_arr.dtype)
    list_of_inputs.append(copy.deepcopy({"input": input_arr, "other": other_arr, "out": out_arr}))

    # Input 7: Boolean
    input_arr = np.array([[True, False], [False, True]], dtype=bool)
    other_arr = np.array([[False, False], [True, True]], dtype=bool)
    out_arr = np.empty(np.broadcast(input_arr, other_arr).shape, dtype=input_arr.dtype)
    list_of_inputs.append(copy.deepcopy({"input": input_arr, "other": other_arr, "out": out_arr}))

    # Input 8: Empty dimension float32 (0,3)
    input_arr = np.empty((0, 3), dtype=np.float32)
    other_arr = np.empty((0, 3), dtype=np.float32)
    out_arr = np.empty(np.broadcast(input_arr, other_arr).shape, dtype=input_arr.dtype)
    list_of_inputs.append(copy.deepcopy({"input": input_arr, "other": other_arr, "out": out_arr}))

    # Input 9: 4D int64 same shape (2,1,3,1)
    input_arr = np.array([[[[1], [2], [3]]],
                          [[[4], [5], [6]]]], dtype=np.int64)
    other_arr = np.array([[[[0], [10], [-1]]],
                          [[[7], [1], [2]]]], dtype=np.int64)
    out_arr = np.empty(np.broadcast(input_arr, other_arr).shape, dtype=input_arr.dtype)
    list_of_inputs.append(copy.deepcopy({"input": input_arr, "other": other_arr, "out": out_arr}))

    # Input 10: uint8 1D
    input_arr = np.array([0, 255, 128, 64, 10], dtype=np.uint8)
    other_arr = np.array([5, 128, 200, 32, 10], dtype=np.uint8)
    out_arr = np.empty(np.broadcast(input_arr, other_arr).shape, dtype=input_arr.dtype)
    list_of_inputs.append(copy.deepcopy({"input": input_arr, "other": other_arr, "out": out_arr}))

    # Input 11: float64 with infinities and signed zeros
    input_arr = np.array([[0.0, -0.0, np.inf], [-np.inf, 3.3, -4.4]], dtype=np.float64)
    other_arr = np.array([[-0.0, 0.0, -np.inf], [np.inf, -3.3, 4.4]], dtype=np.float64)
    out_arr = np.empty(np.broadcast(input_arr, other_arr).shape, dtype=input_arr.dtype)
    list_of_inputs.append(copy.deepcopy({"input": input_arr, "other": other_arr, "out": out_arr}))

    # Input 12: 3D float32 broadcast (1,3,1) vs (2,1,4) -> (2,3,4)
    input_arr = np.array([[[1.0], [2.0], [-3.0]]], dtype=np.float32)
    other_arr = np.array([[[0.5, -1.0, 2.0, -2.5]],
                          [[-0.5, 1.0, -2.0, 2.5]]], dtype=np.float32)
    out_arr = np.empty(np.broadcast(input_arr, other_arr).shape, dtype=input_arr.dtype)
    list_of_inputs.append(copy.deepcopy({"input": input_arr, "other": other_arr, "out": out_arr}))

    return list_of_inputs

generated_inputs["torch.maximum"] = maximum_inputs()

import torch, copy, numpy as np

def median_inputs():
    list_of_inputs = []
    
    # 1) 0-D float64
    input_arr = torch.tensor(3.14, dtype=torch.float64).numpy()
    list_of_inputs.append(copy.deepcopy({"input": input_arr}))
    
    # 2) 1-D float32 even length
    input_arr = torch.tensor([1.0, 2.0, 3.0, 4.0], dtype=torch.float32).numpy()
    list_of_inputs.append(copy.deepcopy({"input": input_arr}))
    
    # 3) 1-D int64 odd length with negatives
    input_arr = torch.tensor([5, -1, 0, 8, 2], dtype=torch.int64).numpy()
    list_of_inputs.append(copy.deepcopy({"input": input_arr}))
    
    # 4) 2-D float32 random
    input_arr = torch.randn(2, 3, dtype=torch.float32).numpy()
    list_of_inputs.append(copy.deepcopy({"input": input_arr}))
    
    # 5) 2-D int16 with negatives and positives
    input_arr = torch.tensor([[-2, -3, 4], [7, 8, -9]], dtype=torch.int16).numpy()
    list_of_inputs.append(copy.deepcopy({"input": input_arr}))
    
    # 6) 3-D float16 linspace
    input_arr = torch.linspace(-1, 1, steps=24, dtype=torch.float16).reshape(2, 3, 4).numpy()
    list_of_inputs.append(copy.deepcopy({"input": input_arr}))
    
    # 7) 1-D float32 non-contiguous slice
    input_arr = torch.arange(20, dtype=torch.float32)[::2].numpy()
    list_of_inputs.append(copy.deepcopy({"input": input_arr}))
    
    # 8) 4-D float64 arange
    input_arr = torch.arange(2*3*4*5, dtype=torch.float64).reshape(2, 3, 4, 5).numpy()
    list_of_inputs.append(copy.deepcopy({"input": input_arr}))
    
    # 9) 1-D float32 with NaN
    input_arr = torch.tensor([1.0, float('nan'), 2.0, 3.0], dtype=torch.float32).numpy()
    list_of_inputs.append(copy.deepcopy({"input": input_arr}))
    
    # 10) 1-D float32 with infinities
    input_arr = torch.tensor([float('-inf'), -1.0, 0.0, float('inf')], dtype=torch.float32).numpy()
    list_of_inputs.append(copy.deepcopy({"input": input_arr}))
    
    # 11) 1-D int8 extremes
    input_arr = torch.tensor([-128, -128, 127, 0, 1], dtype=torch.int8).numpy()
    list_of_inputs.append(copy.deepcopy({"input": input_arr}))
    
    # 12) 3-D float32 with repeated values
    input_arr = torch.full((2, 2, 2), 7.0, dtype=torch.float32).numpy()
    list_of_inputs.append(copy.deepcopy({"input": input_arr}))
    
    return list_of_inputs

