    list_of_inputs.append(copy.deepcopy({
        "input": t.numpy(),
        "nan": 0.0,
        "posinf": 1000.0,
        "neginf": -1000.0,
        "out": out_t.numpy()
    }))

    t = torch.empty((0, 5), dtype=torch.float32)
