    a5 = torch.tensor(
        [
            [[1.0, np.nan, 5.0, -1.0], [np.nan, np.nan, 0.0, 2.0], [3.0, 3.0, 3.0, 3.0]],
            [[4.0, 2.0, 1.0, np.nan], [7.0, -8.0, 9.0, 10.0], [np.nan, np.nan, np.nan, np.nan]],
        ],
        dtype=torch.float32,
    ).numpy()
    dim, keepdim = 1, True
    s = out_shape(a5, dim, keepdim)
