    list_of_inputs.append(copy.deepcopy({"input": a8, "dim": dim, "keepdim": keepdim, "out": out}))

    a9 = torch.tensor(np.arange(16).reshape(2, 2, 2, 2), dtype=torch.float32).numpy()
    a9[0, 0, 1, 1] = np.nan
