    out = np.empty_like(input)
    list_of_inputs.append(copy.deepcopy({"input": input, "out": out}))

    # Input 11: Non-contiguous slice float64
    base = torch.arange(24, dtype=torch.float64).reshape(4, 6).numpy()
    input = base[:, ::2]
    out = np.empty_like(input)
