import torch, copy, math

def fold_inputs():
    list_of_inputs = []

    # Input 1
    output_size = (4, 5)
    kernel_size = (2, 2)
    dilation = 1
    padding = 0
    stride = 1
    H, W = output_size
    kH, kW = kernel_size
    H_blocks = (H + 2*padding - dilation*(kH - 1) - 1) // stride + 1
    W_blocks = (W + 2*padding - dilation*(kW - 1) - 1) // stride + 1
    L = int(H_blocks * W_blocks)
    N, C = 1, 3
    inp = torch.randn(N, C * (kH * kW), L, dtype=torch.float32).numpy()
    list_of_inputs.append(copy.deepcopy({
        "output_size": output_size,
        "kernel_size": kernel_size,
        "dilation": dilation,
        "padding": padding,
        "stride": stride,
        "input": inp
    }))

    # Input 2
    output_size = (7, 7)
    kernel_size = (3, 3)
    dilation = 1
    padding = 1
    stride = 2
    H, W = output_size
    kH, kW = kernel_size
    H_blocks = (H + 2*padding - dilation*(kH - 1) - 1) // stride + 1
    W_blocks = (W + 2*padding - dilation*(kW - 1) - 1) // stride + 1
    L = int(H_blocks * W_blocks)
    N, C = 2, 4
    inp = torch.randn(N, C * (kH * kW), L, dtype=torch.float32).numpy()
    list_of_inputs.append(copy.deepcopy({
        "output_size": output_size,
        "kernel_size": kernel_size,
        "dilation": dilation,
        "padding": padding,
        "stride": stride,
        "input": inp
    }))

    # Input 3
