    Lw = compute_L_dim(output_size[1], kernel_size[1], dilation[1], padding[1], stride[1])
    L = Lh * Lw
    C = 2
    input_tensor = torch.randn((C * kernel_size[0] * kernel_size[1], L), dtype=torch.float64).numpy()
