    p = 0.5
    training = True
    inplace = False
    input_dict = {"input": input_arr, "p": p, "training": training, "inplace": inplace}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 2
    input_arr = np.ones((2, 3), dtype=np.float64)
    p = 0.2
