    tensor = base[::2, ::2].numpy()
    list_of_inputs.append(copy.deepcopy({"tensor": tensor}))

    tensor = torch.randn((1, 5), dtype=torch.float32).numpy()
    list_of_inputs.append(copy.deepcopy({"tensor": tensor}))

    tensor = torch.randn((5, 1), dtype=torch.float32).numpy()
    list_of_inputs.append(copy.deepcopy({"tensor": tensor}))

