    keep = True
    out = torch.empty(expected_shape(inp.shape, dims, keep), dtype=torch.float32).numpy()
    list_of_inputs.append(copy.deepcopy({"input": inp, "dim": dims, "keepdim": keep, "out": out}))

    # Input 8
